import {clawArtwork,clearClaws,pauseClaws} from './claw-motion.mjs?v=7';
import {pauseWeather} from './weather-effects.mjs?v=7';
const NS='http://www.w3.org/2000/svg';let data=null,ready,active=-1,enabled=!matchMedia('(prefers-reduced-motion: reduce)').matches,lastWeatherProgress=0;
const root=document.createElementNS(NS,'svg');root.id='motionScene';root.setAttribute('viewBox','0 0 1440 810');root.setAttribute('aria-hidden','true');document.getElementById('scene').after(root);
function el(tag,attrs={}){const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);return e}
export function motionEnabled(){return enabled}
export function setMotion(value){enabled=value;pauseWeather(!value);pauseClaws(!value);root.classList.toggle('paused',!value);document.getElementById('gameHUD').classList.toggle('motion-paused',!value);document.getElementById('motionToggle').textContent=value?'Pause motion':'Resume motion'}
export async function loadMotion(){ready=fetch('assets/motion/scenes.json?v=7').then(r=>{if(!r.ok)throw Error('Animation artwork unavailable');return r.json()}).then(async d=>{data=d;const sources=[...new Set(d.flatMap(s=>[s.text,...s.layers.map(l=>l.src)]))];await Promise.all(sources.map(src=>new Promise(resolve=>{const im=new Image();im.onload=im.onerror=resolve;im.src=src+'?v=7'})));return d});await ready;return data}
export function showMotion(index,game=false){if(active===index&&root.childElementCount&&data)return true;active=index;lastWeatherProgress=0;clearClaws();root.replaceChildren();root.style.display=data&&index>=0?'block':'none';if(!data||index<0||!data[index])return false;
 const page=data[index],content=el('g',{'class':'scene-content'});root.append(content);root.dataset.scene=index;root.classList.toggle('game-scene',game);root.classList.toggle('paused',!enabled);
 page.layers.forEach((l,i)=>{const g=el('g',{'class':'motion-layer '+l.kind,'data-kind':l.kind});g.dataset.center=l.matrix[4]+l.matrix[0]/2;g.style.setProperty('--delay',`${-(i%5)*1.3}s`);const im=l.kind==='claw'?clawArtwork(l):el('image',{href:l.src+'?v=7',width:1,height:1,transform:`matrix(${l.matrix.join(' ')})`,preserveAspectRatio:'none'});if(index===0&&l.src.endsWith('1-5.png'))g.classList.add('title-ornament');if(index===2&&l.src.endsWith('3-0.png'))g.classList.add('story-plate');if(index===2&&l.src.endsWith('3-1.png'))g.classList.add('story-panel');if(l.clip&&l.kind!=='dragon'&&l.kind!=='cloud'){const id=`clip-${index}-${i}`,clip=el('clipPath',{id,clipPathUnits:'userSpaceOnUse'});const [x,y,width,height]=l.clip;clip.append(el('rect',{x,y,width,height}));root.append(clip);const inner=el('g',{'clip-path':`url(#${id})`});inner.append(im);g.append(inner)}else g.append(im);content.append(g)});
 content.append(el('image',{href:page.text+'?v=7',x:0,y:0,width:1440,height:810,'class':'motion-text'}));return true;
}
export function weatherLevel(level,progress=0){root.dataset.weather=level;root.style.setProperty('--gather',progress);if(active===10&&enabled&&progress>lastWeatherProgress+.06){const bolt=root.querySelector('.lightning');bolt?.animate([{opacity:.35+progress*.4},{opacity:1,offset:.35},{opacity:.2+progress*.8}],{duration:950,easing:'ease-out'});lastWeatherProgress=progress;}if(active===8)root.querySelectorAll('.cloud').forEach(g=>{g.style.translate=`${(720-Number(g.dataset.center))*progress*.65}px 0`;g.style.opacity=.4+progress*.6});}
export function rumble(){root.classList.remove('rumbling');void root.getBoundingClientRect();root.classList.add('rumbling');setTimeout(()=>root.classList.remove('rumbling'),2700)}
export function motionContainer(){return root}